import fs from 'node:fs/promises'
import path from 'node:path'
import os from 'node:os'
import { fileURLToPath } from 'node:url'
// Projects generated by the pinned `shadcn init`; see fixtures/shadcn/README.md.
export const shadcnFixtures = {
  vite: { css: 'src/index.css', source: 'src' },
  next: { css: 'app/globals.css', source: '.' },
  'vite-base': { css: 'src/index.css', source: 'src' },
  'next-base': { css: 'app/globals.css', source: '.' },
} as const
export type ShadcnFixture = keyof typeof shadcnFixtures
export function shadcnFixtureDir(kind: ShadcnFixture) {
  return fileURLToPath(
    new URL('../../fixtures/shadcn/' + kind + '/', import.meta.url),
  )
}
export async function createShadcnProject(kind: ShadcnFixture) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'ombelle-shadcn-'))
  await fs.cp(shadcnFixtureDir(kind), root, { recursive: true })
  return root
}
